class FixtureExecutor implements ReasoningExecutor {
  readonly requests: ReasoningRequest[] = []
  capabilities() { return { maxContextTokens: 100_000, maxOutputTokens: 10_000, structuredOutputSupport: true, maxConcurrency: 2 } }
  async execute(request: ReasoningRequest): Promise<ReasoningResult> {
    this.requests.push(request)
    const input = request.input as Dict
    const source = ((input.allowedSourceCandidateIds as string[] | undefined) ?? [])[0] ?? 'missing-source'
    if (request.operation === 'valuation_assumption_design') {
      const targetFiscalYear = Number(input.targetFiscalYear)
      return { operation: request.operation, operationId: `fixture-${this.requests.length}`, output: { primaryMethod: 'PE', secondaryMethods: ['PB'], targetFiscalYear, scenarios: ['bear', 'base', 'bull'].map((scenarioId, index) => ({ scenarioId, primaryMethod: 'PE', targetFiscalYear, growthRate: [0.05, 0.1, 0.2][index], targetMultiple: [10, 12, 14][index], rationale: `Fixture ${scenarioId} assumption.`, sourceCandidateIds: [source], existingKnowledgeRefs: [] })) } }
    }
    return { operation: request.operation, operationId: `fixture-${this.requests.length}`, output: { sections: [{ sectionId: 'valuation-view', markdown: 'Bounded deterministic interpretation.', sourceCandidateIds: [source], existingKnowledgeRefs: [], valuationResultRefs: ['result-base'] }], proposals: [{ proposalId: 'valuation-view', kind: 'claim', claimType: 'viewpoint', subjectKey: 'company', statement: 'The base-case valuation is a bounded scenario view.', sourceCandidateIds: [source], valuationAssumptionRefs: [], valuationResultRefs: ['result-base'], existingKnowledgeRefs: [] }] } }
  }
}

class SequenceExecutor implements ReasoningExecutor {
  readonly requests: ReasoningRequest[] = []
  private index = 0
  constructor(private readonly outputs: readonly unknown[]) {}
  capabilities() { return { maxContextTokens: 100_000, maxOutputTokens: 10_000, structuredOutputSupport: true, maxConcurrency: 2 } }
  async execute(request: ReasoningRequest): Promise<ReasoningResult> { this.requests.push(request); const output = this.outputs[Math.min(this.index++, this.outputs.length - 1)]; return { operation: request.operation, operationId: `sequence-${this.requests.length}`, output } }
}

class CrossRunExecutor extends FixtureExecutor {
  override async execute(request: ReasoningRequest): Promise<ReasoningResult> {
    const input = request.input as Dict; const ids = (input.allowedSourceCandidateIds as string[]).slice(); const financial = ids.find((id) => id.includes('-financial-'))!; const market = ids.find((id) => id.includes('-market-'))!
    if (request.operation === 'valuation_assumption_design') return { operation: request.operation, operationId: 'cross-run-design', output: { primaryMethod: 'PE', secondaryMethods: ['PB'], targetFiscalYear: 2026, scenarios: ['bear', 'base', 'bull'].map((scenarioId, index) => ({ scenarioId, primaryMethod: 'PE', targetFiscalYear: 2026, growthRate: [0.05, 0.1, 0.2][index], targetMultiple: [10, 12, 14][index], rationale: scenarioId, sourceCandidateIds: [financial], existingKnowledgeRefs: [] })) } }
    return { operation: request.operation, operationId: 'cross-run-synthesis', output: { sections: [{ sectionId: 'valuation-view', markdown: 'Bounded deterministic interpretation.', sourceCandidateIds: [market], existingKnowledgeRefs: [], valuationResultRefs: ['result-base'] }], proposals: [{ proposalId: 'valuation-assumption', kind: 'claim', claimType: 'assumption', subjectKey: 'company', statement: 'Model assumption text.', sourceCandidateIds: [financial], valuationAssumptionRefs: ['base-growth'], valuationResultRefs: [], existingKnowledgeRefs: [] }, { proposalId: 'valuation-view', kind: 'claim', claimType: 'viewpoint', subjectKey: 'company', statement: 'Bounded deterministic interpretation.', sourceCandidateIds: [market], valuationAssumptionRefs: [], valuationResultRefs: ['result-base'], existingKnowledgeRefs: [] }] } }
  }
}

